INSERT INTO _seed_neuro_ap1_context (unit_id,actor_id) SELECT curricular_unit_id,updated_by FROM quiz_topics WHERE id='quiz-topic-neuro-ap1' AND status='published' AND deleted_at IS NULL LIMIT 1;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-049',unit_id,'quiz-topic-neuro-ap1','Que três zonas se distinguem na norma lateral?',NULL,'<strong>Na vista lateral, o crânio pode subdividir-se em três zonas: face, anteriormente, região temporal, ao centro, e região occipital, posteriormente.</strong><p><small>Gray’s Anatomy, 42.ª ed., pp. 560–561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-049-answer','quiz-neuro-ap1-049','Face, temporal e occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-049-incorrect','quiz-neuro-ap1-049','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-050',unit_id,'quiz-topic-neuro-ap1','Que estrutura separa topograficamente as fossas temporal e infratemporal?',NULL,'Os bordos inferior e posterior encontram-se no ângulo da mandíbula; no sexo masculino este ângulo é frequentemente mais evertido, refletindo uma área de inserção maior para o músculo pterigóideo medial na face interna. O <strong>arco zigomático</strong> projeta-se lateralmente relativamente ao resto do crânio, e as fossas temporal e infratemporal comunicam pelo intervalo assim criado; em vida, este espaço é preenchido em grande parte pelo músculo temporal. O zigomático é o principal osso da região malar, em conjunto com as apófises zigomáticas da maxila e do temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-050-answer','quiz-neuro-ap1-050','Arco zigomático',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-050-incorrect','quiz-neuro-ap1-050','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-051',unit_id,'quiz-topic-neuro-ap1','Qual é o limite inferior da fossa temporal?',NULL,'A região temporal divide-se numa fossa temporal superior e numa fossa infratemporal inferior, separadas pela posição do <strong>arco zigomático</strong>. A fossa temporal é limitada inferiormente pelo arco zigomático, superior e posteriormente pelas linhas temporais e anteriormente pela apófise frontal do zigomático.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-051-answer','quiz-neuro-ap1-051','Arco zigomático',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-051-incorrect','quiz-neuro-ap1-051','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-052',unit_id,'quiz-topic-neuro-ap1','Que estruturas limitam superior e posteriormente a fossa temporal?',NULL,'A região temporal divide-se numa fossa temporal superior e numa fossa infratemporal inferior, separadas pela posição do arco zigomático. A fossa temporal é limitada inferiormente pelo arco zigomático, superior e posteriormente pelas <strong>linhas temporais</strong> e anteriormente pela apófise frontal do zigomático. Continua-se inferiormente com a fossa infratemporal, profundamente ao arco zigomático.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-052-answer','quiz-neuro-ap1-052','Linhas temporais',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-052-incorrect','quiz-neuro-ap1-052','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-053',unit_id,'quiz-topic-neuro-ap1','Que estrutura limita anteriormente a fossa temporal?',NULL,'A região temporal divide-se numa fossa temporal superior e numa fossa infratemporal inferior, separadas pela posição do arco zigomático. A fossa temporal é limitada inferiormente pelo arco zigomático, superior e posteriormente pelas linhas temporais e anteriormente pela <strong>apófise frontal do zigomático</strong>. Continua-se inferiormente com a fossa infratemporal, profundamente ao arco zigomático.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-053-answer','quiz-neuro-ap1-053','Apófise frontal do zigomático',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-053-incorrect','quiz-neuro-ap1-053','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-054',unit_id,'quiz-topic-neuro-ap1','Que linha temporal dá inserção à fáscia temporal?',NULL,'A linha temporal inferior torna-se novamente mais evidente ao curvar-se inferiormente sobre a parte posterior da porção escamosa do temporal, formando uma crista supramastoideia na base da apófise mastoideia. A <strong>linha temporal superior</strong> dá inserção à fáscia temporal; a inferior dá inserção ao músculo temporal. O pavimento da fossa temporal é formado superiormente pelos ossos frontal e parietal e inferiormente pela asa maior do esfenóide e parte escamosa do temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-054-answer','quiz-neuro-ap1-054','Linha temporal superior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-054-incorrect','quiz-neuro-ap1-054','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-055',unit_id,'quiz-topic-neuro-ap1','Que linha temporal dá inserção ao músculo temporal?',NULL,'As linhas temporais são frequentemente bem marcadas anteriormente e tornam-se menos proeminentes à medida que arqueiam posteriormente sobre o parietal. A <strong>linha temporal inferior</strong> torna-se novamente mais evidente ao curvar-se inferiormente sobre a parte posterior da porção escamosa do temporal, formando uma crista supramastoideia na base da apófise mastoideia. A linha temporal superior dá inserção à fáscia temporal; a inferior dá inserção ao músculo temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-055-answer','quiz-neuro-ap1-055','Linha temporal inferior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-055-incorrect','quiz-neuro-ap1-055','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-056',unit_id,'quiz-topic-neuro-ap1','Em que crista termina posteriormente a linha temporal inferior?',NULL,'As linhas temporais são frequentemente bem marcadas anteriormente e tornam-se menos proeminentes à medida que arqueiam posteriormente sobre o parietal. A linha temporal inferior torna-se novamente mais evidente ao curvar-se inferiormente sobre a parte posterior da porção escamosa do temporal, formando uma <strong>crista supramastoideia</strong> na base da apófise mastoideia. A linha temporal superior dá inserção à fáscia temporal; a inferior dá inserção ao músculo temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-056-answer','quiz-neuro-ap1-056','Crista supramastoideia',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-056-incorrect','quiz-neuro-ap1-056','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-057',unit_id,'quiz-topic-neuro-ap1','Que quatro ossos constituem o ptérion?',NULL,'<strong>O ptérion é uma região sutural aproximadamente em H no pavimento da fossa temporal, onde se encontram frontal, parietal, asa maior do esfenóide e parte escamosa do temporal.</strong> É um marco topográfico importante porque se sobrepõe habitualmente ao ramo anterior da artéria meníngea média e à fissura lateral do hemisfério cerebral (Ma et al., 2012).<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-057-answer','quiz-neuro-ap1-057','Frontal, parietal, esfenóide e temporal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-057-incorrect','quiz-neuro-ap1-057','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-058',unit_id,'quiz-topic-neuro-ap1','Que osso ocupa o setor anterossuperior do ptérion?',NULL,'Na configuração lateral típica, o osso <strong>frontal</strong> constitui o componente anterossuperior do ptérion; o parietal ocupa o setor posterosuperior; a asa maior do esfenóide situa-se anteroinferiormente; e a parte escamosa do temporal, posteroinferiormente. Esta disposição explica por que motivo o ptérion funciona como referência superficial para a asa maior do esfenóide, para o ramo frontal da artéria meníngea média e, profundamente, para a região da fissura lateral do hemisfério cerebral.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-058-answer','quiz-neuro-ap1-058','Frontal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-058-incorrect','quiz-neuro-ap1-058','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-059',unit_id,'quiz-topic-neuro-ap1','Que osso ocupa o setor posterosuperior do ptérion?',NULL,'Na configuração lateral típica, o osso frontal constitui o componente anterossuperior do ptérion; o <strong>parietal</strong> ocupa o setor posterosuperior; a asa maior do esfenóide situa-se anteroinferiormente; e a parte escamosa do temporal, posteroinferiormente. Esta disposição explica por que motivo o ptérion funciona como referência superficial para a asa maior do esfenóide, para o ramo frontal da artéria meníngea média e, profundamente, para a região da fissura lateral do hemisfério cerebral.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
