INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-061',unit_id,'quiz-topic-neuro-ap1','Que osso ocupa o setor posteroinferior do ptérion?',NULL,'Na configuração lateral típica, o osso frontal constitui o componente anterossuperior do ptérion; o parietal ocupa o setor posterosuperior; a asa maior do esfenóide situa-se anteroinferiormente; e a <strong>parte escamosa do temporal</strong>, posteroinferiormente. Esta disposição explica por que motivo o ptérion funciona como referência superficial para a asa maior do esfenóide, para o ramo frontal da artéria meníngea média e, profundamente, para a região da fissura lateral do hemisfério cerebral.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
