INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-062',unit_id,'quiz-topic-neuro-ap1','Que artéria se relaciona profundamente com o ptérion?',NULL,'Na configuração lateral típica, o osso frontal constitui o componente anterossuperior do ptérion; o parietal ocupa o setor posterosuperior; a asa maior do esfenóide situa-se anteroinferiormente; e a parte escamosa do temporal, posteroinferiormente. Esta disposição explica por que motivo o ptérion funciona como referência superficial para a asa maior do esfenóide, para o ramo frontal da <strong>artéria meníngea média</strong> e, profundamente, para a região da fissura lateral do hemisfério cerebral.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-062-answer','quiz-neuro-ap1-062','Artéria meníngea média',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-062-incorrect','quiz-neuro-ap1-062','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-063',unit_id,'quiz-topic-neuro-ap1','Que ramo da artéria meníngea média se relaciona sobretudo com o ptérion?',NULL,'O ptérion é uma região sutural aproximadamente em H no pavimento da fossa temporal, onde se encontram frontal, parietal, asa maior do esfenóide e parte escamosa do temporal. É um marco topográfico importante porque se sobrepõe habitualmente ao <strong>ramo anterior</strong> da artéria meníngea média e à fissura lateral do hemisfério cerebral (Ma et al., 2012). Corresponde à região da fontanela anterolateral ou esfenoidal do crânio neonatal, que encerra aproximadamente no terceiro mês após o nascimento.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
