INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-069',unit_id,'quiz-topic-neuro-ap1','Que incisura separa as apófises coronóide e condilar?',NULL,'O ramo é uma lâmina óssea que se projeta superiormente a partir do corpo da mandíbula e dá inserção ao masséter na sua face lateral. Superiormente apresenta duas apófises proeminentes: a apófise coronóide, anterior, e a apófise condilar, posterior, separadas pela <strong>incisura mandibular</strong>. O músculo temporal insere-se na apófise coronóide; a apófise condilar articula-se com a fossa mandibular do temporal na articulação temporomandibular.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
