INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-071',unit_id,'quiz-topic-neuro-ap1','Que apófise mandibular articula com a fossa mandibular?',NULL,'Superiormente apresenta duas apófises proeminentes: a apófise coronóide, anterior, e a <strong>apófise condilar</strong>, posterior, separadas pela incisura mandibular. O músculo temporal insere-se na apófise coronóide; a apófise condilar articula-se com a fossa mandibular do temporal na articulação temporomandibular. Os bordos inferior e posterior encontram-se no ângulo da mandíbula; no sexo masculino este ângulo é frequentemente mais evertido, refletindo uma área de inserção maior para o músculo pterigóideo medial na face interna.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
