INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-075',unit_id,'quiz-topic-neuro-ap1','Que estrutura limita posteriormente a fossa mandibular?',NULL,'Também são visíveis a fossa mandibular e a eminência articular, a <strong>lâmina timpânica</strong>, o meato acústico externo e as apófises mastoideia e estilóide. A fossa mandibular é limitada anteriormente pela eminência articular e posteriormente pela lâmina timpânica. A eminência articular constitui a superfície sobre a qual o côndilo mandibular desliza durante os movimentos da mandíbula e contribui para evitar a luxação da articulação temporomandibular.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
