INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-077',unit_id,'quiz-topic-neuro-ap1','Que depressão superficial se relaciona com a parede lateral do antro mastoideu?',NULL,'O bordo externo do meato é rugoso e dá inserção à parte cartilagínea do meato. Superior e posteriormente ao meato existe uma pequena depressão, o <strong>triângulo suprameático</strong>, relacionada com a parede lateral do antro mastoideu. A apófise mastoideia é uma projeção inferior do temporal, situada posteroinferiormente ao meato acústico externo, e dá inserção ao músculo esternocleidomastóideo.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-077-answer','quiz-neuro-ap1-077','Triângulo suprameático',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-077-incorrect','quiz-neuro-ap1-077','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-078',unit_id,'quiz-topic-neuro-ap1','Que apófise se situa posteroinferiormente ao meato acústico externo?',NULL,'Superior e posteriormente ao meato existe uma pequena depressão, o triângulo suprameático, relacionada com a parede lateral do antro mastoideu. A <strong>apófise mastoideia</strong> é uma projeção inferior do temporal, situada posteroinferiormente ao meato acústico externo, e dá inserção ao músculo esternocleidomastóideo. Posteriormente relaciona-se com o ângulo posteroinferior do parietal pela sutura parietomastoideia e com a parte escamosa do occipital pela sutura occipitomastoideia.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-078-answer','quiz-neuro-ap1-078','Apófise mastoideia',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-078-incorrect','quiz-neuro-ap1-078','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-079',unit_id,'quiz-topic-neuro-ap1','Que músculo se insere na apófise mastoideia?',NULL,'Superior e posteriormente ao meato existe uma pequena depressão, o triângulo suprameático, relacionada com a parede lateral do antro mastoideu. A apófise mastoideia é uma projeção inferior do temporal, situada posteroinferiormente ao meato acústico externo, e dá inserção ao músculo <strong>esternocleidomastóideo</strong>. Posteriormente relaciona-se com o ângulo posteroinferior do parietal pela sutura parietomastoideia e com a parte escamosa do occipital pela sutura occipitomastoideia.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
