INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-084-incorrect','quiz-neuro-ap1-084','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-085',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea forma cerca de 80% do teto da fossa infratemporal?',NULL,'A fossa infratemporal tem teto e paredes anterior, lateral e medial, permanecendo aberta posteroinferiormente. Cerca de 80% do teto é formado pela <strong>face infratemporal da asa maior do esfenóide</strong>; a parte restante é formada pela face infratemporal do osso temporal.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, p. 664.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-085-answer','quiz-neuro-ap1-085','Asa maior do esfenóide',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-085-incorrect','quiz-neuro-ap1-085','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-086',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea forma anteriormente a parede medial da fossa infratemporal?',NULL,'A parede medial da fossa infratemporal é formada anteriormente pela <strong>lâmina pterigóidea lateral do esfenóide</strong>. Mais posteromedialmente, relaciona-se com a faringe e com os músculos tensor e elevador do véu palatino.<p><small>Gray’s Anatomy, 42.ª ed., cap. 38, p. 664.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
